const raw = $json.jobs_block.replace(/\r\n/g, '\n');
const thinkFlag = $json.enable_thinking === 'Thorough (with thinking)';
const blocks = raw.split(/\n*={3,}\n*/).map(b => b.trim()).filter(Boolean);

return blocks.map(block => {
  const lines = block.split('\n');
  const companyLine = lines.find(l => l.toLowerCase().startsWith('company:'));
  const company_name = companyLine ? companyLine.replace(/company:\s*/i, '').trim() : 'Unknown';
  const job_description = lines.filter(l => !l.toLowerCase().startsWith('company:')).join('\n').trim();
  return { json: { company_name, job_description, think: thinkFlag } };
});

