  if (valid.length > 0) {
    validated_selection[heading] = valid;
    tailored_bullets += `### ${heading}\n` + valid.map(b => `- ${b}`).join('\n') + '\n\n';
  }
}
return { json: { tailored_bullets: tailored_bullets.trim(), validated_selection } };

